import { mkdirSync, writeFileSync } from 'node:fs';
import { installCommands } from '../src/commands/catalog.js';
import { listCommandSpecs } from '../src/commands/registry.js';

installCommands();

const specs = listCommandSpecs();
const lines = [
  '# Command API',
  '',
  'Generated from the command registry by `npm run docs:api`. Do not edit this file by hand.',
  'The headset UI, the in-app assistant, and external agents all call these commands.',
  '',
  'A call returns `{ status: "ok", result }` or `{ status: "error", error }`.',
  'Destructive commands called by an assistant or an external agent return `{ status: "confirmation_required", command, params, description }` until the call is repeated with confirmation.',
  'Clicks in the headset pass as the user, so they count as confirmation.',
  '',
  `Command count: ${specs.length}.`,
  '',
];

for (const spec of specs) {
  lines.push(`## \`${spec.name}\``);
  lines.push('');
  lines.push(spec.description);
  lines.push('');
  lines.push(`- Destructive: ${spec.destructive ? 'yes' : 'no'}`);
  lines.push(`- Exposed to the in-app model: ${spec.aiVisible === false ? 'no' : 'yes'}`);
  lines.push('');
  lines.push('### Params');
  lines.push('');
  lines.push('```json');
  lines.push(JSON.stringify(spec.params, null, 2));
  lines.push('```');
  lines.push('');
  lines.push('### Result');
  lines.push('');
  lines.push('```json');
  lines.push(JSON.stringify(spec.result, null, 2));
  lines.push('```');
  lines.push('');
}

const body = `${lines.join('\n')}`;
mkdirSync(new URL('../docs/', import.meta.url), { recursive: true });
writeFileSync(new URL('../docs/API.md', import.meta.url), body);
console.log(`Wrote docs/API.md (${specs.length} commands)`);
